mapper.select:
select g.id as goods_id, g.name as goods_name, substr(o.add_time,1,10) as day, sum(og.number) as sales_volume, sum(og.number * og.price) as order_amount from dts_order o inner join dts_order_goods og on o.id = og.order_id inner join dts_goods g on og.goods_id = g.id where o.order_status in(201, 301, 401, 402)
and substr(o.add_time,1,10) >= #{startDate}
and substr(o.add_time,1,10) <= #{endDate}
and g.id = #{goodsId}
and o.user_id = #{userId}
group by g.id, g.name, substr(o.add_time,1,10) order by day desc, order_amount desc

select u.id as user_id, u.username as user_name, substr(o.add_time,1,10) as day, sum(og.number) as sales_volume, sum(og.number * og.price) as order_amount from dts_order o inner join dts_order_goods og on o.id = og.order_id inner join dts_user u on o.user_id = u.id where o.order_status in(201, 301, 401, 402)
and substr(o.add_time,1,10) >= #{startDate}
and substr(o.add_time,1,10) <= #{endDate}
and og.goods_id = #{goodsId}
and u.id = #{userId}
group by u.id, u.username, substr(o.add_time,1,10) order by day desc, order_amount desc

select
substr(o.add_time,1,7) as month,
sum(og.number) as sales_volume,
sum(og.number * og.price) as order_amount
from dts_order o
inner join dts_order_goods og on o.id = og.order_id
where o.order_status in(201, 301, 401, 402)

    and substr(o.add_time,1,10) >= #{startDate}


    and substr(o.add_time,1,10) <= #{endDate}


    and og.goods_id = #{goodsId}


    and o.user_id = #{userId}

group by substr(o.add_time,1,7)
order by month desc
